import{_ as a,c as o,o as s,ae as t}from"./chunks/framework.DEXG3EuZ.js";const u=JSON.parse('{"title":"请求与 OpenAPI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/request.md","filePath":"guide/request.md","lastUpdated":1792605191000}'),c={name:"guide/request.md"};function d(i,e,n,p,r,l){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="请求与-openapi" tabindex="-1">请求与 OpenAPI <a class="header-anchor" href="#请求与-openapi" aria-label="Permalink to &quot;请求与 OpenAPI&quot;">​</a></h1><h2 id="调用链" tabindex="-1">调用链 <a class="header-anchor" href="#调用链" aria-label="Permalink to &quot;调用链&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>View / Query composable</span></span>
<span class="line"><span>  -&gt; src/api/modules/*.ts</span></span>
<span class="line"><span>  -&gt; apiClient</span></span>
<span class="line"><span>  -&gt; Axios interceptor</span></span>
<span class="line"><span>  -&gt; ApiResponse&lt;T&gt; / ApiError</span></span></code></pre></div><p>页面不得直接导入 Axios。模块函数负责 URL、参数和返回类型；页面用 <code>isApiError(error)</code> 收窄未知错误。</p><h2 id="类型" tabindex="-1">类型 <a class="header-anchor" href="#类型" aria-label="Permalink to &quot;类型&quot;">​</a></h2><ul><li><code>ApiResponse&lt;T&gt;</code>：后端统一响应体。</li><li><code>ApiError</code>：<code>business | http | timeout | network | cancelled | unknown</code>。</li><li><code>PaginationParams</code> / <code>PaginationResponse&lt;T&gt;</code>：分页契约。</li></ul><p>请求拦截器按需加入 Bearer Token 和 <code>X-Request-ID</code>。响应拦截器区分业务错误与 HTTP 错误；401 通过运行时 handler 清理会话并跳转，不让 client 直接导入 Router。</p><p><code>src/api/modules/projects.ts</code> 定义项目 CRUD 的前端契约；当前 Gin 未注册对应 Project 路由。<code>/examples/workspace</code> 使用 TanStack Query 管理分页列表和 Mutation，页面不保存 Server State。统一响应的 <code>code</code> 接受整个 2xx 区间，因此 HTTP 201 创建响应仍能正确解包。</p><h2 id="openapi" tabindex="-1">OpenAPI <a class="header-anchor" href="#openapi" aria-label="Permalink to &quot;OpenAPI&quot;">​</a></h2><p>仓库带有包含 Gin 业务接口与 FastAPI Streaming 契约的 <code>openapi/schema.yaml</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api:generate</span></span></code></pre></div><p>生成结果为 <code>src/types/api/generated.d.ts</code>。真实项目替换 Schema 或命令输入地址后，应提交 Schema 与生成文件，并在 CI 运行 typecheck。不要手工修改生成文件。</p><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><p><code>VITE_*</code> 会进入浏览器产物，禁止放 API 密钥。示例 Token 使用 <code>sessionStorage</code>；生产优先使用 SameSite、Secure、HttpOnly Cookie/BFF。重定向只接受以单 <code>/</code> 开头的站内路径。</p><h2 id="rest-契约与请求取消" tabindex="-1">REST 契约与请求取消 <a class="header-anchor" href="#rest-契约与请求取消" aria-label="Permalink to &quot;REST 契约与请求取消&quot;">​</a></h2><p>单应用请求客户端同时接受真实服务的 <code>code: 0</code>／<code>message</code> 和旧 Mock 的 2xx 业务码／<code>msg</code>，统一解包 <code>data</code>，失败仍为 <code>ApiError</code>。HTTP 2xx 不等于业务成功。</p><p>以下函数直接返回解包后的数据，并通过 <code>ApiError</code> 拒绝失败请求。读取操作应转发 Query 的 <code>AbortSignal</code>。收藏写入使用 bootstrap 统一配置的登录客户端，不接受调用方提供的用户 ID。</p><p>单应用通过 <code>VITE_AI_API_BASE_URL</code>（默认 <code>/api/ai</code>）请求建议，通过 <code>VITE_AI_API_TARGET</code> 配置开发代理；常规业务请求发往 Gin。JSON 请求位于 <code>src/api/modules/ai.ts</code>，流式协议仍由 Provider/composable 管理。</p><p>响应包装兼容不会自动转换路径或业务字段。单应用商品模块仍使用 <code>/api/products</code> 与多语言 <code>name</code>／<code>priceCents</code>，当前 Gin 商品接口为 <code>/api/product/list</code> 与 <code>title</code>／<code>price</code>；登录也存在 <code>name</code>／<code>token</code> 与 <code>username</code>／<code>accessToken</code> 的差异。完整联调前需要核对其余契约或增加明确的领域适配。新增收藏路径已与 Gin 对齐，但鉴权仍需要兼容的已签发 JWT。</p>`,19)])])}const m=a(c,[["render",d]]);export{u as __pageData,m as default};
